// Some portions generated by Codex
import { resourceNodeId } from "./rdf-terms.ts";

export const AUTOMATIC_SEARCH_STATEMENT_LIMIT = 100_000;

/** Unknown and invalid sizes never enable the Enter-to-search fallback. */
export function requiresManualRepositorySearch(size: number | null | undefined): boolean {
  return typeof size !== "number" || !Number.isSafeInteger(size) || size < 0 || size > AUTOMATIC_SEARCH_STATEMENT_LIMIT;
}

/** Keep exact resource lookup distinct from an expensive repository label scan. */
export function exactSearchResource(term: string): string | undefined {
  const resource = resourceNodeId(term);
  return resource !== undefined && (term.startsWith("<_:") || /^<?([A-Za-z][A-Za-z0-9+.-]*:\/\/|urn:)/i.test(term))
    ? resource : undefined;
}
